  "elev": 1200,
  "best": "全年",
  "lat": 24.07,
  "lng": 101.59,
  "desc": "新平戛洒坝子的花腰傣，因妇女束五色花腰带得名，是傣族中最古老的一支。服饰艳丽精美，银饰繁多，风情独特。每年农历正月花街节，花腰傣姑娘身着盛装赛装、丢包，歌舞欢腾，民族风情浓郁动人。",
  "wiki": "花腰傣",
  "img": "images_gxyn/s504.svg"
